export const meta = {
  "slug": "chat",
  "name": "Chat",
  "family": "AI",
  "collection": "AI",
  "component": "createLinearChat"
};

export function createLinearChat(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderLinearScene(svg, current);
  };
  render();
  const controller = bindLinearScene(root, current);
  return {
    replay: controller.replay,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
  };
}
